-- Упражнения книги 19, глава 24 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-list-all', 0, 'func', 'Домены по состояниям', 'Вывод virsh list --all — таблица: строка заголовка " Id   Name   State", строка из одних дефисов, затем по строке на домен: числовой Id (или дефис, если домен не запущен), имя без пробелов и состояние. Состояние может состоять из нескольких слов ("shut off", "in shutdown"). Напишите функцию domains_by_state(text): верните словарь «состояние → отсортированный по алфавиту список имён». Заголовок, разделитель и пустые строки пропускайте; пустой вывод даёт пустой словарь.', 'def domains_by_state(text):
    pass
', 'Разбейте строку на три части: s.split(None, 2) даёт Id, имя и всё остальное как состояние.', '{"func": "domains_by_state", "tests": [{"args": [" Id   Name      State\n---------------------------\n 1    web01     running\n 3    build     paused\n -    db01      shut off\n -    old       shut off\n"], "expected": {"running": ["web01"], "paused": ["build"], "shut off": ["db01", "old"]}}, {"args": [" Id   Name   State\n--------------------\n\n"], "expected": {}}, {"args": ["\n Id    Name       State\n------------------------------\n 12    ci-1       in shutdown\n 13    ci-2       pmsuspended\n 14    ci-3       running\n 15    ci-4       running\n\n"], "expected": {"in shutdown": ["ci-1"], "pmsuspended": ["ci-2"], "running": ["ci-3", "ci-4"]}}, {"args": [" Id   Name   State\n------------------------\n 7    z      crashed\n -    b      crashed\n -    a      shut off\n"], "expected": {"crashed": ["b", "z"], "shut off": ["a"]}}, {"args": [" Id   Name   State\n------------------------\n 2    b      running\n 1    a      running\n"], "expected": {"running": ["a", "b"]}}, {"args": [""], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-domain-summary', 1, 'func', 'Память и vCPU из XML домена', 'Дано XML описание домена (вывод virsh dumpxml). Элементы memory и currentMemory содержат целое число в единицах из атрибута unit; без атрибута единица — KiB. Встречаются единицы: b или bytes (1 байт), KiB или k (1024 байта), MiB или M, GiB или G (степени 1024). Если currentMemory нет, он равен memory. Элемент vcpu содержит максимум vCPU, а атрибут current (если есть) — сколько включено при старте, иначе столько же, сколько максимум. Напишите функцию domain_summary(xml): верните кортеж (имя, memory_мибибайт, current_мибибайт, vcpu_максимум, vcpu_сейчас). Мибибайты округляйте вверх до целого; пробелы вокруг текста в элементах отбрасывайте.', 'def domain_summary(xml):
    pass
', 'ElementTree: root.find(''memory''), e.get(''unit'', ''KiB''). Переведите в байты умножением, затем -(-n // 2**20) — округление вверх.', '{"func": "domain_summary", "tests": [{"args": ["<domain type=''kvm''>\n  <name>web01</name>\n  <uuid>3e3fce45-4f53-4fa7-bb32-11f34168b82b</uuid>\n  <memory unit=''GiB''>2</memory>\n  <vcpu placement=''static''>4</vcpu>\n</domain>"], "expected": {"__tuple__": ["web01", 2048, 2048, 4, 4]}}, {"args": ["<domain type=''kvm''>\n  <name>db</name>\n  <memory unit=''KiB''>1048576</memory>\n  <currentMemory unit=''MiB''>512</currentMemory>\n  <vcpu placement=''static'' current=''2''>8</vcpu>\n</domain>"], "expected": {"__tuple__": ["db", 1024, 512, 8, 2]}}, {"args": ["<domain type=''qemu''><name>a</name><memory unit=''bytes''>1073741824</memory><vcpu>1</vcpu></domain>"], "expected": {"__tuple__": ["a", 1024, 1024, 1, 1]}}, {"args": ["<domain type=''kvm''><name>tiny</name><memory>3000</memory><currentMemory unit=''k''>1025</currentMemory><vcpu>1</vcpu></domain>"], "expected": {"__tuple__": ["tiny", 3, 2, 1, 1]}}, {"args": ["<domain type=''kvm''><name>big</name><memory unit=''G''>4</memory><currentMemory unit=''GiB''>3</currentMemory><vcpu current=''1''>16</vcpu></domain>"], "expected": {"__tuple__": ["big", 4096, 3072, 16, 1]}}, {"args": ["<domain type=''kvm''>\n  <name>  spaced </name>\n  <memory unit=''MiB''> 1536 </memory>\n  <currentMemory unit=''b''>1048577</currentMemory>\n  <vcpu> 2 </vcpu>\n</domain>"], "expected": {"__tuple__": ["spaced", 1536, 2, 2, 2]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-validate-domain', 2, 'func', 'Проверка описания домена', 'Напишите функцию validate_domain(xml), которая проверяет XML домена по правилам. Диски — элементы ./devices/disk, сетевые карты — ./devices/interface. (1) dup-target:<dev> — два диска с одинаковым target dev. (2) no-source:<dev> — диск с type=''file'' (источник — атрибут file у source) или type=''block'' (атрибут dev у source), у которого нет элемента source или нужный атрибут пуст; исключение — device=''cdrom'', ему источник не нужен (без атрибута device диск считается device=''disk''; если у диска нет target, вместо <dev> пишите ?). (3) bus-mismatch:<dev> — имя начинается с vd, а шина не virtio; начинается с hd, а шина не ide; начинается с sd, а шина не scsi, sata или usb (другие префиксы, например xvd, не проверяются; диски без bus не проверяются). (4) dup-mac:<mac> — повтор MAC-адреса среди сетевых карт, сравнение без учёта регистра, в сообщении — адрес в нижнем регистре. Карты без mac пропускайте. Верните отсортированный список уникальных сообщений.', 'def validate_domain(xml):
    pass
', 'Один проход по дискам: множество увиденных dev, словарь допустимых шин по префиксу. Сообщения складывайте в set и в конце sorted().', '{"func": "validate_domain", "tests": [{"args": ["<domain type=''kvm''><name>t</name><devices>\n  <disk type=''file'' device=''disk''><driver name=''qemu'' type=''qcow2''/><source file=''/i/a.qcow2''/><target dev=''vda'' bus=''virtio''/></disk>\n  <disk type=''file'' device=''cdrom''><driver name=''qemu'' type=''raw''/><target dev=''sda'' bus=''sata''/><readonly/></disk>\n  <interface type=''network''><mac address=''52:54:00:00:00:01''/><source network=''default''/><model type=''virtio''/></interface>\n</devices></domain>"], "expected": []}, {"args": ["<domain type=''kvm''><name>t</name><devices>\n  <disk type=''file'' device=''disk''><source file=''/i/a.qcow2''/><target dev=''vda'' bus=''virtio''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/i/b.qcow2''/><target dev=''vda'' bus=''virtio''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/i/c.qcow2''/><target dev=''vdb'' bus=''virtio''/></disk>\n</devices></domain>"], "expected": ["dup-target:vda"]}, {"args": ["<domain type=''kvm''><name>t</name><devices>\n  <disk type=''file'' device=''disk''><driver name=''qemu'' type=''raw''/><target dev=''vda'' bus=''virtio''/></disk>\n  <disk type=''block'' device=''disk''><source dev=''''/><target dev=''vdb'' bus=''virtio''/></disk>\n  <disk type=''block'' device=''disk''><source dev=''/dev/vg0/data''/><target dev=''vdc'' bus=''virtio''/></disk>\n  <disk type=''file'' device=''cdrom''><target dev=''sda'' bus=''sata''/></disk>\n</devices></domain>"], "expected": ["no-source:vda", "no-source:vdb"]}, {"args": ["<domain type=''kvm''><name>t</name><devices>\n  <disk type=''file'' device=''disk''><source file=''/a''/><target dev=''vda'' bus=''sata''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/b''/><target dev=''sdb'' bus=''virtio''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/c''/><target dev=''sdc'' bus=''usb''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/d''/><target dev=''hda'' bus=''ide''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/e''/><target dev=''hdb'' bus=''scsi''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/f''/><target dev=''xvda'' bus=''xen''/></disk>\n  <disk type=''file'' device=''disk''><source file=''/g''/><target dev=''sdd'' bus=''scsi''/></disk>\n</devices></domain>"], "expected": ["bus-mismatch:hdb", "bus-mismatch:sdb", "bus-mismatch:vda"]}, {"args": ["<domain type=''kvm''><name>t</name><devices>\n  <interface type=''network''><mac address=''52:54:00:AA:BB:CC''/><source network=''default''/></interface>\n  <interface type=''bridge''><mac address=''52:54:00:aa:bb:cc''/><source bridge=''br0''/></interface>\n  <interface type=''bridge''><mac address=''52:54:00:aa:bb:dd''/><source bridge=''br0''/></interface>\n  <interface type=''bridge''><source bridge=''br1''/></interface>\n  <interface type=''bridge''><source bridge=''br2''/></interface>\n</devices></domain>"], "expected": ["dup-mac:52:54:00:aa:bb:cc"]}, {"args": ["<domain type=''kvm''><name>t</name><devices>\n  <disk type=''file'' device=''disk''><target dev=''vda'' bus=''virtio''/></disk>\n  <disk type=''block'' device=''disk''><source dev=''/dev/sdb''/><target dev=''vda'' bus=''sata''/></disk>\n  <interface type=''network''><mac address=''52:54:00:00:00:01''/></interface>\n  <interface type=''network''><mac address=''52:54:00:00:00:01''/></interface>\n</devices></domain>"], "expected": ["bus-mismatch:vda", "dup-mac:52:54:00:00:00:01", "dup-target:vda", "no-source:vda"]}, {"args": ["<domain type=''kvm''><name>t</name></domain>"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-build-xml', 3, 'func', 'Собрать XML домена', 'Напишите функцию build_domain_xml(spec): spec — словарь с ключами name, memory_mib (целое), vcpus (целое), disks — список словарей {file, target} и network — имя сети libvirt или пустая строка/None. Верните строку ровно такого вида (отступы — по два пробела на уровень, одинарные кавычки в атрибутах, строки разделены \n, в конце один \n): <domain type=''kvm''>, <name>…</name>, <memory unit=''KiB''>…</memory> (мибибайты, умноженные на 1024), <vcpu>…</vcpu>, <os> с вложенными <type>hvm</type> и <boot dev=''hd''/>, затем <devices> и в нём по порядку все диски и сетевая карта, затем закрывающие теги. Диск: <disk type=''file'' device=''disk''> с вложенными <driver name=''qemu'' type=''…''/> (qcow2, если путь оканчивается на .qcow2, иначе raw), <source file=''…''/> и <target dev=''…'' bus=''…''/>; шина по первым двум буквам target: vd — virtio, sd — sata, hd — ide. Карта (если network не пуст): <interface type=''network''> с <source network=''…''/> и <model type=''virtio''/>. В тексте имени экранируйте & < >, в значениях атрибутов file и network дополнительно одинарную кавычку как &apos;.', 'def build_domain_xml(spec):
    pass
', 'Собирайте список строк и делайте ''\n''.join(lines) + ''\n''. Экранирование: xml.sax.saxutils.escape(s, {"''": ''&apos;''}).', '{"func": "build_domain_xml", "tests": [{"args": [{"name": "web01", "memory_mib": 2048, "vcpus": 2, "disks": [{"file": "/var/lib/libvirt/images/web01.qcow2", "target": "vda"}], "network": "default"}], "expected": "<domain type=''kvm''>\n  <name>web01</name>\n  <memory unit=''KiB''>2097152</memory>\n  <vcpu>2</vcpu>\n  <os>\n    <type>hvm</type>\n    <boot dev=''hd''/>\n  </os>\n  <devices>\n    <disk type=''file'' device=''disk''>\n      <driver name=''qemu'' type=''qcow2''/>\n      <source file=''/var/lib/libvirt/images/web01.qcow2''/>\n      <target dev=''vda'' bus=''virtio''/>\n    </disk>\n    <interface type=''network''>\n      <source network=''default''/>\n      <model type=''virtio''/>\n    </interface>\n  </devices>\n</domain>\n"}, {"args": [{"name": "bare", "memory_mib": 512, "vcpus": 1, "disks": [], "network": ""}], "expected": "<domain type=''kvm''>\n  <name>bare</name>\n  <memory unit=''KiB''>524288</memory>\n  <vcpu>1</vcpu>\n  <os>\n    <type>hvm</type>\n    <boot dev=''hd''/>\n  </os>\n  <devices>\n  </devices>\n</domain>\n"}, {"args": [{"name": "db&co", "memory_mib": 4096, "vcpus": 4, "disks": [{"file": "/dev/vg0/db.img", "target": "sda"}, {"file": "/srv/x.qcow2", "target": "hdb"}], "network": null}], "expected": "<domain type=''kvm''>\n  <name>db&amp;co</name>\n  <memory unit=''KiB''>4194304</memory>\n  <vcpu>4</vcpu>\n  <os>\n    <type>hvm</type>\n    <boot dev=''hd''/>\n  </os>\n  <devices>\n    <disk type=''file'' device=''disk''>\n      <driver name=''qemu'' type=''raw''/>\n      <source file=''/dev/vg0/db.img''/>\n      <target dev=''sda'' bus=''sata''/>\n    </disk>\n    <disk type=''file'' device=''disk''>\n      <driver name=''qemu'' type=''qcow2''/>\n      <source file=''/srv/x.qcow2''/>\n      <target dev=''hdb'' bus=''ide''/>\n    </disk>\n  </devices>\n</domain>\n"}, {"args": [{"name": "q", "memory_mib": 1, "vcpus": 8, "disks": [{"file": "/srv/it''s<a>.qcow2", "target": "vdb"}], "network": "br''x"}], "expected": "<domain type=''kvm''>\n  <name>q</name>\n  <memory unit=''KiB''>1024</memory>\n  <vcpu>8</vcpu>\n  <os>\n    <type>hvm</type>\n    <boot dev=''hd''/>\n  </os>\n  <devices>\n    <disk type=''file'' device=''disk''>\n      <driver name=''qemu'' type=''qcow2''/>\n      <source file=''/srv/it&apos;s&lt;a&gt;.qcow2''/>\n      <target dev=''vdb'' bus=''virtio''/>\n    </disk>\n    <interface type=''network''>\n      <source network=''br&apos;x''/>\n      <model type=''virtio''/>\n    </interface>\n  </devices>\n</domain>\n"}, {"args": [{"name": "two", "memory_mib": 1536, "vcpus": 3, "disks": [{"file": "/a.raw", "target": "vda"}, {"file": "/b.QCOW2", "target": "vdb"}], "network": "isolated"}], "expected": "<domain type=''kvm''>\n  <name>two</name>\n  <memory unit=''KiB''>1572864</memory>\n  <vcpu>3</vcpu>\n  <os>\n    <type>hvm</type>\n    <boot dev=''hd''/>\n  </os>\n  <devices>\n    <disk type=''file'' device=''disk''>\n      <driver name=''qemu'' type=''raw''/>\n      <source file=''/a.raw''/>\n      <target dev=''vda'' bus=''virtio''/>\n    </disk>\n    <disk type=''file'' device=''disk''>\n      <driver name=''qemu'' type=''raw''/>\n      <source file=''/b.QCOW2''/>\n      <target dev=''vdb'' bus=''virtio''/>\n    </disk>\n    <interface type=''network''>\n      <source network=''isolated''/>\n      <model type=''virtio''/>\n    </interface>\n  </devices>\n</domain>\n"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-choose-pool', 4, 'func', 'Куда положить том', 'Даны описания пулов хранения (вывод virsh pool-dumpxml): корневой элемент pool с атрибутом type, элементами name и available (свободное место; число в единицах атрибута unit — bytes, KiB, MiB или GiB, без атрибута bytes; нет элемента — считайте 0). Напишите функцию choose_pool(pool_xmls, size_bytes): выберите пул для нового тома размером size_bytes. Пулы типов iscsi, iscsi-direct, scsi и mpath пропускайте: тома в них создать через libvirt нельзя. Из остальных подходят те, где available не меньше size_bytes; из подходящих берите пул с наименьшим available (так остаются большие куски), при равенстве — с меньшим именем по алфавиту. Верните имя пула или пустую строку, если подходящего нет.', 'def choose_pool(pool_xmls, size_bytes):
    pass
', 'Для каждого пула переведите available в байты и сравнивайте кортежи (available, name) — min даст нужный выбор.', '{"func": "choose_pool", "tests": [{"args": [["<pool type=''dir''>\n  <name>default</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>500</available>\n</pool>", "<pool type=''logical''>\n  <name>fast</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>300</available>\n</pool>", "<pool type=''netfs''>\n  <name>big</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>5000</available>\n</pool>"], 250], "expected": "fast"}, {"args": [["<pool type=''dir''>\n  <name>default</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>500</available>\n</pool>", "<pool type=''logical''>\n  <name>fast</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>300</available>\n</pool>"], 600], "expected": ""}, {"args": [["<pool type=''iscsi''>\n  <name>lun</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>1000000000000</available>\n</pool>", "<pool type=''dir''>\n  <name>d</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>100</available>\n</pool>"], 200], "expected": ""}, {"args": [["<pool type=''dir''>\n  <name>b</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available unit=''GiB''>2</available>\n</pool>", "<pool type=''dir''>\n  <name>a</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available unit=''MiB''>2048</available>\n</pool>", "<pool type=''fs''>\n  <name>c</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available unit=''GiB''>3</available>\n</pool>"], 1000], "expected": "a"}, {"args": [["<pool type=''mpath''>\n  <name>m</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>9999</available>\n</pool>", "<pool type=''scsi''>\n  <name>s</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>9999</available>\n</pool>", "<pool type=''iscsi-direct''>\n  <name>i</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>9999</available>\n</pool>"], 1], "expected": ""}, {"args": [[], 10], "expected": ""}, {"args": [["<pool type=''dir''>\n  <name>exact</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available unit=''KiB''>4</available>\n</pool>", "<pool type=''dir''>\n  <name>more</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>4097</available>\n</pool>"], 4096], "expected": "exact"}, {"args": [["<pool type=''dir''><name>none</name></pool>", "<pool type=''dir''>\n  <name>x</name>\n  <capacity unit=''bytes''>1000</capacity>\n  <allocation unit=''bytes''>0</allocation>\n  <available>7</available>\n</pool>"], 0], "expected": "none"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-volume-report', 5, 'func', 'Объёмы томов и переподписка', 'Вывод virsh vol-list --pool NAME --details — таблица: заголовок " Name Path Type Capacity Allocation", строка дефисов и по строке на том: имя, путь, тип, затем Capacity и Allocation, каждое — число с точкой и единица (B, KiB, MiB, GiB или TiB, степени 1024, отделены пробелом). Имя и путь без пробелов, поэтому в строке тома ровно семь слов. Capacity — размер, который видит гость, Allocation — сколько реально занято на хосте. Напишите функцию volume_report(text, pool_gib): верните кортеж (сумма Capacity в GiB, сумма Allocation в GiB, переподписан ли пул), числа округляйте до двух знаков; пул переподписан, если сумма Capacity строго больше pool_gib. Строки, где не семь слов (заголовок, разделитель, пустые), пропускайте.', 'def volume_report(text, pool_gib):
    pass
', 'Каждое значение умножьте на множитель единицы и складывайте в байтах (лучше Decimal), в GiB переводите в конце.', '{"func": "volume_report", "tests": [{"args": [" Name          Path                                  Type   Capacity     Allocation\n---------------------------------------------------------------------------------\n db01.qcow2    /var/lib/libvirt/images/db01.qcow2    file   50.00 GiB    4.25 GiB\n web01.qcow2   /var/lib/libvirt/images/web01.qcow2   file   20.00 GiB    1.50 GiB\n seed.iso      /var/lib/libvirt/images/seed.iso      file   366.00 KiB   366.00 KiB\n", 100], "expected": {"__tuple__": [70.0, 5.75, false]}}, {"args": [" Name          Path                                  Type   Capacity     Allocation\n---------------------------------------------------------------------------------\n db01.qcow2    /var/lib/libvirt/images/db01.qcow2    file   50.00 GiB    4.25 GiB\n web01.qcow2   /var/lib/libvirt/images/web01.qcow2   file   20.00 GiB    1.50 GiB\n seed.iso      /var/lib/libvirt/images/seed.iso      file   366.00 KiB   366.00 KiB\n", 69.5], "expected": {"__tuple__": [70.0, 5.75, true]}}, {"args": [" Name   Path                   Type   Capacity   Allocation\n------------------------------------------------------\n a      /dev/vg0/a             block  512.00 MiB  512.00 MiB\n b      /dev/vg0/b             block  1.50 GiB    1.50 GiB\n", 2], "expected": {"__tuple__": [2.0, 2.0, false]}}, {"args": [" Name   Path   Type   Capacity   Allocation\n------------------------------------------\n\n", 10], "expected": {"__tuple__": [0.0, 0.0, false]}}, {"args": [" Name       Path                   Type   Capacity   Allocation\n---------------------------------------------------------------\n big.img    /srv/images/big.img    file   2.00 TiB   0.00 B\n small.img  /srv/images/small.img  file   1.00 GiB   0.00 B\n", 2000], "expected": {"__tuple__": [2049.0, 0.0, true]}}, {"args": [" Name   Path     Type   Capacity     Allocation\n------------------------------------------------\n x      /x.img   file   10.00 GiB    10.00 GiB\n y      /y.img   file   10.00 GiB    10.00 GiB\n", 20], "expected": {"__tuple__": [20.0, 20.0, false]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-check-network', 6, 'func', 'Проверка сети libvirt', 'Дано XML виртуальной сети libvirt: элемент ip с атрибутами address (адрес шлюза/моста) и netmask, внутри него dhcp с необязательным range (start, end) и любым числом host (mac, name, ip). Напишите функцию check_network(xml): верните отсортированный список уникальных сообщений. Диапазон: range-outside — start или end вне подсети; range-order — start больше end; range-has-gateway — start <= адрес шлюза <= end (проверяется, только если порядок верный). Каждый host: если нет mac, name или ip — host-incomplete (дальше такой host не проверяется); иначе повторы среди проверенных host: dup-mac:<mac> (MAC сравнивается без учёта регистра, в сообщении — в нижнем регистре), dup-name:<name>, dup-ip:<ip> (сообщение при втором и следующих повторах); затем ровно одно из: host-outside:<ip> (вне подсети), host-gateway:<ip> (равен адресу шлюза), host-in-range:<ip> (внутри динамического диапазона, включая границы) — это правило задачи: статические адреса держат вне пула раздачи. Используйте модуль ipaddress.', 'def check_network(xml):
    pass
', 'ipaddress.ip_interface(''10.0.0.1/255.255.255.0'') даёт и адрес (.ip), и подсеть (.network); адреса сравниваются операторами <, <=.', '{"func": "check_network", "tests": [{"args": ["<network>\n  <name>default</name>\n  <forward mode=''nat''/>\n  <bridge name=''virbr0''/>\n  <ip address=''192.168.122.1'' netmask=''255.255.255.0''>\n    <dhcp>\n      <range start=''192.168.122.2'' end=''192.168.122.254''/>\n      <host mac=''52:54:00:6b:3c:58'' name=''web01'' ip=''192.168.122.10''/>\n    </dhcp>\n  </ip>\n</network>"], "expected": ["host-in-range:192.168.122.10"]}, {"args": ["<network><name>n</name><ip address=''10.0.0.1'' netmask=''255.255.255.0''><dhcp>\n  <range start=''10.0.1.5'' end=''10.0.0.50''/>\n</dhcp></ip></network>"], "expected": ["range-order", "range-outside"]}, {"args": ["<network><name>n</name><ip address=''10.0.0.1'' netmask=''255.255.255.0''><dhcp>\n  <range start=''10.0.0.90'' end=''10.0.0.20''/>\n</dhcp></ip></network>"], "expected": ["range-order"]}, {"args": ["<network><name>n</name><ip address=''10.0.0.1'' netmask=''255.255.255.0''><dhcp>\n  <range start=''10.0.0.1'' end=''10.0.0.20''/>\n</dhcp></ip></network>"], "expected": ["range-has-gateway"]}, {"args": ["<network><name>n</name><ip address=''172.16.0.1'' netmask=''255.255.0.0''><dhcp>\n  <range start=''172.16.1.10'' end=''172.16.1.250''/>\n  <host mac=''52:54:00:00:00:01'' name=''a'' ip=''172.16.0.10''/>\n  <host mac=''52:54:00:00:00:02'' name=''b'' ip=''172.16.0.10''/>\n  <host mac=''52:54:00:00:00:01'' name=''c'' ip=''172.16.0.12''/>\n  <host mac=''52:54:00:00:00:04'' name=''a'' ip=''172.16.1.20''/>\n  <host mac=''52:54:00:00:00:05'' name=''e'' ip=''192.168.0.5''/>\n  <host mac=''52:54:00:00:00:06'' name=''f'' ip=''172.16.0.1''/>\n  <host name=''g'' ip=''172.16.0.30''/>\n</dhcp></ip></network>"], "expected": ["dup-ip:172.16.0.10", "dup-mac:52:54:00:00:00:01", "dup-name:a", "host-gateway:172.16.0.1", "host-in-range:172.16.1.20", "host-incomplete", "host-outside:192.168.0.5"]}, {"args": ["<network><name>iso</name><ip address=''192.168.50.1'' netmask=''255.255.255.0''/></network>"], "expected": []}, {"args": ["<network><name>n</name><ip address=''10.9.8.1'' netmask=''255.255.255.252''><dhcp>\n  <range start=''10.9.8.2'' end=''10.9.8.3''/>\n</dhcp></ip></network>"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-check-seed', 7, 'func', 'Проверка сида cloud-init', 'Сид NoCloud — два файла: user-data и meta-data. Напишите функцию check_seed(user_data, meta_data) (обе — строки), которая проверяет их по маленькому подмножеству формата и возвращает отсортированный список сообщений. user-data: первая строка (без хвостовых пробелов) должна быть ровно #cloud-config, иначе user-data:header. Остальные строки (нумерация с единицы, шапка — строка 1): пустые и начинающиеся с # (после пробелов) пропускаются; допустимы только три вида — «ключ: значение» (ключ из строчных латинских букв, цифр и _, начинается не с цифры; значение непустое), «ключ:» (открывает список) и «  - элемент» (ровно два пробела, дефис, пробел, непустой элемент), причём элемент допустим, только пока открыт список: список открывается строкой «ключ:» и закрывается любой следующей строкой «ключ…:». Любая другая строка — user-data:syntax:<номер строки>. Дальше: список без единого элемента — user-data:empty:<ключ>; ключи packages и runcmd, заданные скаляром ("packages: nginx"), — user-data:list:<ключ>; ssh_pwauth скаляром не true и не false — user-data:bool:ssh_pwauth. meta-data: должна быть строка вида "instance-id: значение" без отступа с непустым значением, иначе meta-data:instance-id (строки с # и пустые не считаются).', 'def check_seed(user_data, meta_data):
    pass
', 'Три регулярных выражения: ключ со значением или без, элемент списка. Ведите переменную «какой список открыт» и счётчик элементов на ключ.', '{"func": "check_seed", "tests": [{"args": ["#cloud-config\nhostname: web01\nssh_pwauth: false\npackages:\n  - nginx\n  - curl\nruncmd:\n  - systemctl enable --now nginx\n", "instance-id: web01-001\nlocal-hostname: web01\n"], "expected": []}, {"args": ["hostname: web01\npackages:\n  - nginx\n", ""], "expected": ["meta-data:instance-id", "user-data:header"]}, {"args": ["#cloud-config\n# comment\nhostname web01\npackages:\n   - nginx\n  - curl\n\nssh_pwauth: maybe\n", "# seed\ninstance-id:\nlocal-hostname: web01\n"], "expected": ["meta-data:instance-id", "user-data:bool:ssh_pwauth", "user-data:syntax:3", "user-data:syntax:5"]}, {"args": ["#cloud-config\npackages: nginx\nruncmd:\nusers:\n  - name\n", "  instance-id: web01\nlocal-hostname: web01\n"], "expected": ["meta-data:instance-id", "user-data:empty:runcmd", "user-data:list:packages"]}, {"args": ["#cloud-config\n  - stray\nhostname: x\n  - stray2\n", "instance-id: web01-001\nlocal-hostname: web01\n"], "expected": ["user-data:syntax:2", "user-data:syntax:4"]}, {"args": ["", ""], "expected": ["meta-data:instance-id", "user-data:header"]}, {"args": ["#cloud-config\nhostname: web01\nssh_pwauth: false\npackages:\n  - nginx\n  - curl\nruncmd:\n  - systemctl enable --now nginx\n", "instance-id: x\n"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-snapshot-delete', 8, 'func', 'Удаление снимка', 'Вывод virsh snapshot-list ДОМЕН --parent — таблица: заголовок " Name Creation Time State Parent", строка дефисов и по строке на снимок: имя (первое слово), время (три слова), состояние и имя родителя (последнее слово; дефис, если родителя нет). Снимки перечислены в порядке создания. Напишите функцию delete_snapshot(table, name, with_children): верните список кортежей (имя, родитель) оставшихся снимков в том же порядке, родитель — пустая строка у корней. С with_children=True (virsh snapshot-delete --children) удаляются снимок name и все его потомки на любую глубину. С with_children=False изменения снимка вливаются в потомков: удаляется только он, а его непосредственные дети получают в родители его родителя. Если снимка name нет, список остаётся прежним.', 'def delete_snapshot(table, name, with_children):
    pass
', 'Имя — первое слово, родитель — последнее. Потомок ли узел: идите по родителям вверх, пока не встретите name.', '{"func": "delete_snapshot", "tests": [{"args": [" Name      Creation Time               State      Parent\n-------------------------------------------------------------\n base      2026-11-01 10:00:00 +0300   shutoff    -\n upgrade   2026-11-01 11:00:00 +0300   running    base\n fix       2026-11-02 09:30:00 +0300   running    upgrade\n other     2026-11-02 10:00:00 +0300   shutoff    base\n final     2026-11-03 08:00:00 +0300   running    fix\n", "upgrade", true], "expected": [{"__tuple__": ["base", ""]}, {"__tuple__": ["other", "base"]}]}, {"args": [" Name      Creation Time               State      Parent\n-------------------------------------------------------------\n base      2026-11-01 10:00:00 +0300   shutoff    -\n upgrade   2026-11-01 11:00:00 +0300   running    base\n fix       2026-11-02 09:30:00 +0300   running    upgrade\n other     2026-11-02 10:00:00 +0300   shutoff    base\n final     2026-11-03 08:00:00 +0300   running    fix\n", "upgrade", false], "expected": [{"__tuple__": ["base", ""]}, {"__tuple__": ["fix", "base"]}, {"__tuple__": ["other", "base"]}, {"__tuple__": ["final", "fix"]}]}, {"args": [" Name      Creation Time               State      Parent\n-------------------------------------------------------------\n base      2026-11-01 10:00:00 +0300   shutoff    -\n upgrade   2026-11-01 11:00:00 +0300   running    base\n fix       2026-11-02 09:30:00 +0300   running    upgrade\n other     2026-11-02 10:00:00 +0300   shutoff    base\n final     2026-11-03 08:00:00 +0300   running    fix\n", "base", false], "expected": [{"__tuple__": ["upgrade", ""]}, {"__tuple__": ["fix", "upgrade"]}, {"__tuple__": ["other", ""]}, {"__tuple__": ["final", "fix"]}]}, {"args": [" Name      Creation Time               State      Parent\n-------------------------------------------------------------\n base      2026-11-01 10:00:00 +0300   shutoff    -\n upgrade   2026-11-01 11:00:00 +0300   running    base\n fix       2026-11-02 09:30:00 +0300   running    upgrade\n other     2026-11-02 10:00:00 +0300   shutoff    base\n final     2026-11-03 08:00:00 +0300   running    fix\n", "base", true], "expected": []}, {"args": [" Name      Creation Time               State      Parent\n-------------------------------------------------------------\n base      2026-11-01 10:00:00 +0300   shutoff    -\n upgrade   2026-11-01 11:00:00 +0300   running    base\n fix       2026-11-02 09:30:00 +0300   running    upgrade\n other     2026-11-02 10:00:00 +0300   shutoff    base\n final     2026-11-03 08:00:00 +0300   running    fix\n", "final", true], "expected": [{"__tuple__": ["base", ""]}, {"__tuple__": ["upgrade", "base"]}, {"__tuple__": ["fix", "upgrade"]}, {"__tuple__": ["other", "base"]}]}, {"args": [" Name      Creation Time               State      Parent\n-------------------------------------------------------------\n base      2026-11-01 10:00:00 +0300   shutoff    -\n upgrade   2026-11-01 11:00:00 +0300   running    base\n fix       2026-11-02 09:30:00 +0300   running    upgrade\n other     2026-11-02 10:00:00 +0300   shutoff    base\n final     2026-11-03 08:00:00 +0300   running    fix\n", "nope", true], "expected": [{"__tuple__": ["base", ""]}, {"__tuple__": ["upgrade", "base"]}, {"__tuple__": ["fix", "upgrade"]}, {"__tuple__": ["other", "base"]}, {"__tuple__": ["final", "fix"]}]}, {"args": [" Name   Creation Time               State      Parent\n-----------------------------------------------------\n a      2026-11-01 10:00:00 +0000   shutoff    -\n b      2026-11-01 11:00:00 +0000   shutoff    -\n", "a", false], "expected": [{"__tuple__": ["b", ""]}]}, {"args": [" Name   Creation Time               State           Parent\n----------------------------------------------------------\n s1     2026-11-01 10:00:00 +0000   disk-snapshot   -\n s2     2026-11-01 11:00:00 +0000   disk-snapshot   s1\n s3     2026-11-01 12:00:00 +0000   disk-snapshot   s2\n", "s2", false], "expected": [{"__tuple__": ["s1", ""]}, {"__tuple__": ["s3", "s1"]}]}, {"args": [" Name   Creation Time   State   Parent\n------------------------------------\n\n", "x", true], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 24, 'la24-lifecycle', 9, 'func', 'Жизненный цикл домена', 'Модель жизни домена под командами virsh. Состояния: "gone" (домена нет), "shut off", "running", "paused". Флаг persistent говорит, есть ли у домена сохранённое описание. Команды: define — если домена нет, он появляется остановленным и постоянным; если есть, он становится постоянным (состояние не меняется). start — только из "shut off" в "running". shutdown — только из "running": домен выключается (если он постоянный — в "shut off", а временный исчезает: "gone"). destroy — из "running" или "paused", результат как у shutdown. suspend — из "running" в "paused"; resume — из "paused" в "running". undefine — только для постоянного существующего домена: остановленный исчезает ("gone", persistent False), работающий или приостановленный остаётся в своём состоянии, но становится временным. Любая команда, которая не разрешена правилами (в том числе неизвестная), не меняет ничего и даёт ошибку "<команда>:<состояние до команды>". Напишите функцию simulate_domain(state, persistent, commands): верните кортеж (состояние, persistent, список ошибок по порядку).', 'def simulate_domain(state, persistent, commands):
    pass
', 'Цепочка if/elif по команде и состоянию, а в else — запись ошибки. Не забудьте запомнить состояние до команды.', '{"func": "simulate_domain", "tests": [{"args": ["gone", false, ["define", "start", "suspend", "resume", "shutdown"]], "expected": {"__tuple__": ["shut off", true, []]}}, {"args": ["gone", false, ["start", "destroy", "undefine"]], "expected": {"__tuple__": ["gone", false, ["start:gone", "destroy:gone", "undefine:gone"]]}}, {"args": ["running", true, ["undefine", "shutdown", "start"]], "expected": {"__tuple__": ["gone", false, ["start:gone"]]}}, {"args": ["running", true, ["undefine", "undefine", "destroy"]], "expected": {"__tuple__": ["gone", false, ["undefine:running"]]}}, {"args": ["paused", true, ["shutdown", "resume", "suspend", "destroy", "undefine", "define"]], "expected": {"__tuple__": ["shut off", true, ["shutdown:paused"]]}}, {"args": ["shut off", true, ["destroy", "reboot", "start", "start"]], "expected": {"__tuple__": ["running", true, ["destroy:shut off", "reboot:shut off", "start:running"]]}}, {"args": ["running", false, ["define", "undefine", "destroy", "define"]], "expected": {"__tuple__": ["shut off", true, []]}}, {"args": ["shut off", true, []], "expected": {"__tuple__": ["shut off", true, []]}}]}');
